const r = $input.first().json;
const out = r.stdout || '';
const line = out.split('\n').reverse().find(l => l.startsWith('METRICS_JSON:'));
if (!line) throw new Error('No METRICS_JSON line in pipeline output. exitCode=' + r.exitCode + '. ' + 'Most likely n8n is running an OLD copy of moveinsync_ratings_pipeline.py (search it for METRICS_JSON) or project_dir points to the wrong folder. ' + 'stdout tail: ' + out.slice(-400) + ' | stderr tail: ' + String(r.stderr || '').slice(-400));
const m = JSON.parse(line.slice(13));
const cfg = $('Config').first().json;
const drop = (m.prior_avg !== null && m.prior_avg !== undefined) ? +(m.prior_avg - m.cur_avg).toFixed(2) : 0;
const rising = (m.themes || []).filter(t => t.change >= Number(cfg.theme_threshold_pts));
const badVersions = (m.worst_versions || []).filter(v => v.avg <= m.cur_avg - 0.3);
const alert = drop >= Number(cfg.drop_threshold_stars) || rising.length > 0 || badVersions.length > 0;
return [{ json: { ...m, drop, rising, badVersions, alert } }];

