const m = $('Parse metrics').first().json;
const g = $input.first().json;
const raw = g.candidates?.[0]?.content?.parts?.[0]?.text || '';
let a = null;
try { a = JSON.parse(raw); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => esc(String(s ?? '').trim().slice(0, n));
const pct = x => (x === null || x === undefined) ? 'n/a' : (x < 1 ? x.toFixed(2) : x.toFixed(1)) + '%';
const label = t => String(t).replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const sign = x => (x > 0 ? '+' : '') + x;

const reasons = [];
if (m.drop > 0) reasons.push(`average down ${m.drop}`);
if ((m.rising || []).length) reasons.push(`rising: ${m.rising.map(t => label(t.theme)).join(', ')}`);
if ((m.badVersions || []).length) reasons.push(`weak version: v${m.badVersions[0].version}`);

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Play Store ratings report · ${m.date}` } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Recent average*\n${m.cur_avg} (prior ${m.prior_avg})` },
    { type: 'mrkdwn', text: `*Lifetime store rating*\n${m.store_rating}` },
    { type: 'mrkdwn', text: `*1-2 star share*\n${pct(m.neg_share_cur)} (prior ${pct(m.neg_share_prior)})` },
    { type: 'mrkdwn', text: `*Reviews analysed*\n${m.cur_reviews}` },
    { type: 'mrkdwn', text: `*Developer reply rate*\n${pct(m.reply_rate)}` },
    { type: 'mrkdwn', text: `*Why this report fired*\n${reasons.join('; ') || 'routine weekly report'}` } ] },
];

if (!a) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: cut(raw, 2800) || 'Gemini returned no text.' } });
  return [{ json: { text: `Play Store ratings report ${m.date}`, blocks } }];
}

blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*What is happening*\n${cut(a.summary, 1200)}` } });
blocks.push({ type: 'divider' });

const stat = {}; (m.themes || []).forEach(t => { stat[t.theme] = t; });
const causes = (a.causes || []).slice(0, 4).map((c, i) => {
  const s = stat[c.theme];
  const nums = s ? ` · ${s.share_now}% of 1-2 star reviews (${sign(s.change)} pts vs prior)` : '';
  return `*${i + 1}. ${label(c.theme || 'cause')}*${nums}\n${cut(c.explanation, 500)}` + (c.evidence ? `\n_${cut(c.evidence, 200)}_` : '');
}).join('\n\n');
if (causes) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Why the ratings are where they are*\n\n${causes}`.slice(0, 2900) } });

if ((m.worst_versions || []).length) {
  const lines = m.worst_versions.map(v => `• v${esc(v.version)}: ${v.avg} average from ${v.reviews} reviews`).join('\n');
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Worst-rated app versions*\n${lines}` + (a.version_note ? `\n${cut(a.version_note, 400)}` : '') } });
}
blocks.push({ type: 'divider' });

const rank = { P1: 1, P2: 2, P3: 3 };
const actions = (a.actions || []).slice(0, 6).sort((x, y) => (rank[x.priority] || 9) - (rank[y.priority] || 9));
const depts = [...new Set(actions.map(x => x.department).filter(Boolean))];
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Next actions, by department*\nDepartments involved: ${esc(depts.join(', ') || 'n/a')}` } });
actions.forEach(x => {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text:
    `*${cut(x.priority, 3)} · ${cut(x.department, 40)}* · ${cut(x.timeline, 20)}\n${cut(x.action, 400)}\n*First step:* ${cut(x.first_step, 300)}\n*How we will know it worked:* ${cut(x.metric, 200)}` } });
});

const replies = (a.replies || []).slice(0, 3);
if (replies.length) {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Draft replies, a human must approve before posting*\n' + replies.map(r => `• \`${esc(String(r.id).slice(0, 8))}\` ${cut(r.reply, 400)}`).join('\n') } });
}
const tail = [a.watch_next_week ? `*Watch next week:* ${cut(a.watch_next_week, 300)}` : '', 'Generated by n8n and Gemini from public Play Store reviews. Theme tags are AI-assisted; spot-check them in the dashboard.'].filter(Boolean).join('\n');
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: tail }] });

return [{ json: { text: `Play Store ratings report ${m.date}: avg ${m.cur_avg} (prior ${m.prior_avg})`, blocks } }];

const m = $input.first().json;
const pct = x => (x === null || x === undefined) ? 'n/a' : (x < 1 ? x.toFixed(2) : x.toFixed(1)) + '%';
const label = t => String(t).replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const sign = x => (x > 0 ? '+' : '') + x;
const themes = (m.themes || []).slice(0, 4).map(t => `• *${label(t.theme)}*: ${t.share_now}% of 1-2 star reviews (${sign(t.change)} pts vs prior)`).join('\n');
const vers = (m.worst_versions || []).map(v => `• v${v.version}: ${v.avg} average from ${v.reviews} reviews`).join('\n');
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Play Store ratings stable · ${m.date}` } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Recent average*\n${m.cur_avg} (prior ${m.prior_avg})` },
    { type: 'mrkdwn', text: `*Lifetime store rating*\n${m.store_rating}` },
    { type: 'mrkdwn', text: `*1-2 star share*\n${pct(m.neg_share_cur)} (prior ${pct(m.neg_share_prior)})` },
    { type: 'mrkdwn', text: `*Reviews analysed*\n${m.cur_reviews}` },
    { type: 'mrkdwn', text: `*Developer reply rate*\n${pct(m.reply_rate)}` } ] },
];
if (themes) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Top complaint themes this period*\n${themes}` } });
if (vers) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Lowest-rated app versions*\n${vers}` } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'No alert: no rating drop above threshold, no rising theme and no weak app version this week.' }] });
return [{ json: { text: `Play Store ratings stable ${m.date}: avg ${m.cur_avg} (prior ${m.prior_avg})`, blocks } }];
